<?php
declare(strict_types=1);
require dirname(__DIR__).'/src/Core.php';use Wams\Core;
session_name('WAMSSESSID');session_start(['cookie_httponly'=>true,'cookie_samesite'=>'Lax','cookie_secure'=>isset($_SERVER['HTTPS'])]);$c=new Core();$error='';
function h(mixed$v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}function go(string$u):never{header('Location:'.$u);exit;}
$path=trim((string)parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH),'/');$page=(string)($_GET['page']??($path==='login'?'login':'launcher'));
try{
 if($page==='login'&&$_SERVER['REQUEST_METHOD']==='POST'){if($c->login(trim((string)$_POST['username']),(string)$_POST['password']))go('/');$error='Anmeldung fehlgeschlagen.';}
 if($page==='logout'){session_destroy();go('/login');}
 if($page!=='login')$user=$c->requireUser();
 if(isset($user)&&$_SERVER['REQUEST_METHOD']==='POST'){$c->checkCsrf();
  if($page==='user-create'){if(!$user['is_global_admin'])throw new RuntimeException('Nicht erlaubt.');$c->db->prepare('INSERT INTO users VALUES(?,?,?,?,?,?)')->execute([$c->id(),trim((string)$_POST['username']),password_hash((string)$_POST['password'],PASSWORD_ARGON2ID),0,1,gmdate('c')]);go('/?page=users');}
  if($page==='user-access'){if(!$user['is_global_admin'])throw new RuntimeException('Nicht erlaubt.');$uid=(string)$_POST['user'];$app=(string)$_POST['app'];$mode=(string)$_POST['mode'];$c->db->prepare('DELETE FROM user_apps WHERE user_id=? AND installed_app_id=?')->execute([$uid,$app]);if($mode!=='none')$c->db->prepare('INSERT INTO user_apps VALUES(?,?,?)')->execute([$uid,$app,$mode==='admin'?1:0]);go('/?page=users');}
  if($page==='repo-refresh'){if(!$user['is_global_admin'])throw new RuntimeException('Nicht erlaubt.');$c->refreshRepo();go('/?page=store');}
  if($page==='app-install'){if(!$user['is_global_admin'])throw new RuntimeException('Nicht erlaubt.');$id=(string)$_POST['catalog_id'];$found=null;foreach($c->catalog()as$a)if(($a['id']??'')===$id)$found=$a;if(!$found)throw new RuntimeException('Katalog-App nicht gefunden.');$c->install($found);go('/?page=apps');}
 }
 if(isset($user)&&$page==='config-export'){$app=$c->installed((string)$_GET['id']);if(!$c->canUse($user,$app['id'])){http_response_code(403);exit;}$f=$c->cfg['instances'].'/'.$app['id'].'/app/csv-reporting.json';if(!is_file($f))file_put_contents($f,"{}\n");header('Content-Type: application/json');header('Content-Disposition: attachment; filename="csv-reporting.json"');readfile($f);exit;}
 if(isset($user)&&$page==='config-import'&&$_SERVER['REQUEST_METHOD']==='POST'){$app=$c->installed((string)$_POST['id']);if(!$c->canAdmin($user,$app['id'])){http_response_code(403);exit;}if((int)($_FILES['config']['size']??0)>5242880)throw new RuntimeException('csv-reporting.json ist größer als 5 MiB.');$raw=(string)file_get_contents($_FILES['config']['tmp_name']??'');$decoded=json_decode($raw,true);if(!is_array($decoded))throw new RuntimeException('csv-reporting.json ist ungültig.');file_put_contents($c->cfg['instances'].'/'.$app['id'].'/app/csv-reporting.json',json_encode($decoded,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)."\n",LOCK_EX);go('/?page=run&id='.$app['id'].'&view=admin');}
 if(isset($user)&&$page==='run'){$app=$c->installed((string)$_GET['id']);if(!$c->canUse($user,$app['id'])){http_response_code(403);exit;}$admin=(string)($_GET['view']??'app')==='admin';if($admin&&!$c->canAdmin($user,$app['id'])){http_response_code(403);exit;}$dir=$c->cfg['instances'].'/'.$app['id'].'/app';$entry=$dir.'/'.($admin?'admin.php':'index.php');$webapp_managed=true;$webapp_admin=$admin;$webapp_global_admin=(bool)$user['is_global_admin'];$webapp_user=$user;$webapp_instance=$app;$webapp_config_file=$dir.'/csv-reporting.json';echo'<div class="overlay">';if($c->canAdmin($user,$app['id'])){echo'<a href="/?page=run&amp;id='.h($app['id']).'&amp;view='.($admin?'app':'admin').'">'.($admin?'App':'Admin').'</a>';echo'<a href="/?page=config-export&amp;id='.h($app['id']).'">Export</a>';echo'<form method="post" action="/?page=config-import" enctype="multipart/form-data" style="margin:0"><input type="hidden" name="csrf" value="'.h($c->csrf()).'"><input type="hidden" name="id" value="'.h($app['id']).'"><label style="display:block;background:#111923e8;border:1px solid #293747;color:#fff;border-radius:4px;padding:8px 11px;font:13px system-ui;cursor:pointer">Import<input type="file" name="config" accept="application/json,.json" required style="display:none" onchange="this.form.submit()"></label></form>';}echo'<a href="/">Zurück</a></div>';chdir($dir);require$entry;exit;}
}catch(Throwable$e){$error=$e->getMessage();}
if($page==='login'):?><!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="/assets/style.css"><title>WAMS Login</title></head><body class="login-page"><main class="login"><h1>WAMS</h1><?php if($error):?><div class="error"><?=h($error)?></div><?php endif?><form method="post"><label>Benutzername</label><input name="username" required autofocus><label>Passwort</label><input type="password" name="password" required><button>Anmelden</button></form></main></body></html><?php exit;endif;
if($page==='launcher'):$q=$c->db->query('SELECT * FROM installed_apps ORDER BY name');$apps=array_filter($q->fetchAll(),fn($a)=>$c->canUse($user,$a['id']));?><!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="/assets/style.css"><title>WAMS</title></head><body class="launcher"><header class="launcher-bar"><strong>WAMS</strong><div><?php if($user['is_global_admin']):?><a class="btn gray" href="/?page=apps">Verwaltung</a><?php endif?> <a class="btn gray" href="/?page=logout">Abmelden</a></div></header><main class="grid"><?php foreach($apps as$a):?><a class="tile" href="/?page=run&amp;id=<?=h($a['id'])?>"><strong><?=h($a['name'])?></strong></a><?php endforeach?><?php if(!$apps):?><div class="panel"><div class="body">Keine Apps verfügbar.</div></div><?php endif?></main></body></html><?php exit;endif;
if(!$user['is_global_admin']){http_response_code(403);exit;}
?><!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="/assets/style.css"><title>WAMS Verwaltung</title></head><body><div class="layout"><aside class="side"><div class="brand">WAMS</div><nav class="nav"><a href="/?page=apps">Apps</a><a href="/?page=store">App Store</a><a href="/?page=users">Benutzer</a><a href="/">Launcher</a><a href="/?page=logout">Abmelden</a></nav></aside><section class="main"><header class="top"><strong>Verwaltung</strong><span><?=h($user['username'])?></span></header><main class="content"><?php if($error):?><div class="error"><?=h($error)?></div><?php endif?>
<?php if($page==='apps'):?><section class="panel"><div class="head">Installierte Apps</div><div class="body"><table><tr><th>Name</th><th>Konfiguration</th></tr><?php foreach($c->db->query('SELECT * FROM installed_apps ORDER BY name')as$a):?><tr><td><a href="/?page=run&amp;id=<?=h($a['id'])?>"><?=h($a['name'])?></a></td><td><a href="/?page=config-export&amp;id=<?=h($a['id'])?>">Export</a> · <a href="/?page=run&amp;id=<?=h($a['id'])?>&amp;view=admin">Admin</a></td></tr><?php endforeach?></table></div></section>
<?php elseif($page==='store'):?><form method="post" action="/?page=repo-refresh"><input type="hidden" name="csrf" value="<?=h($c->csrf())?>"><button>App Store aktualisieren</button></form><div class="grid" style="margin-top:14px"><?php foreach($c->catalog()as$a):?><section class="tile"><strong><?=h($a['name'])?></strong><form method="post" action="/?page=app-install"><input type="hidden" name="csrf" value="<?=h($c->csrf())?>"><input type="hidden" name="catalog_id" value="<?=h($a['id'])?>"><button style="margin-top:14px">Installieren</button></form></section><?php endforeach?></div>
<?php elseif($page==='users'):$users=$c->db->query('SELECT * FROM users ORDER BY username')->fetchAll();$apps=$c->db->query('SELECT * FROM installed_apps ORDER BY name')->fetchAll();?><div class="grid"><section class="panel"><div class="head">Benutzer anlegen</div><div class="body"><form method="post" action="/?page=user-create"><input type="hidden" name="csrf" value="<?=h($c->csrf())?>"><label>Benutzername</label><input name="username" required><label>Passwort</label><input type="password" name="password" minlength="12" required><button style="margin-top:14px">Anlegen</button></form></div></section><section class="panel"><div class="head">App-Zugriff</div><div class="body"><form method="post" action="/?page=user-access"><input type="hidden" name="csrf" value="<?=h($c->csrf())?>"><label>Benutzer</label><select name="user"><?php foreach($users as$u):if($u['is_global_admin'])continue;?><option value="<?=h($u['id'])?>"><?=h($u['username'])?></option><?php endforeach?></select><label>App</label><select name="app"><?php foreach($apps as$a):?><option value="<?=h($a['id'])?>"><?=h($a['name'])?></option><?php endforeach?></select><label>Zugriff</label><select name="mode"><option value="none">Kein Zugriff</option><option value="user">App</option><option value="admin">App + Admin</option></select><button style="margin-top:14px">Speichern</button></form></div></section></div>
